serviceCalls:
window.omniEdu?.createTeachingBookChapter({
    bookId: detail.book.id, title: chapterDraft.title.trim(), summary: chapterDraft.summary.trim(), contentType: chapterDraft.contentType,
    learningObjectives: splitLines(chapterDraft.objectives), prerequisites: splitLines(chapterDraft.prerequisites), order: detail.chapters.length,
})

window.omniEdu?.upsertTeachingBookBlock({
    pageId: blockPageId, title: blockDraft.title.trim(), type: blockDraft.type, status: blockDraft.status,
    payload: { text: blockDraft.text }, sourceAnchors: sourceAnchor ? [sourceAnchor] : editingBlock?.sourceAnchors ?? [],
    order: editingBlock?.order ?? detail.blocks.filter((block) => block.pageId === blockPageId).length,
}, editingBlock?.id, editingBlock?.version)

originalGuards:
if (!bookDraft.title.trim()) {
    showError(null, '讲义标题不能为空。');
    return;
}

if (!detail || !chapterDraft.title.trim()) {
    showError(null, '请选择讲义并填写章节标题。');
    return;
}

if (!detail || !pageChapterId || !pageDraft.title.trim()) {
    showError(null, '请选择章节并填写页面标题。');
    return;
}

if (!detail || !blockPageId || !blockDraft.text.trim()) {
    showError(null, '请选择页面并填写内容块正文。');
    return;
}

addedGuards:
if (editingBlockId && !editingBlock) {
    showError(null, '当前内容块已不可用，草稿仍保留，请放弃本地修改后重新读取。');
    return;
}

originalGuards:
if (!detail || !sourceDraft.ref.trim() || !sourceDraft.title.trim()) {
    showError(null, '来源引用和标题不能为空。');
    return;
}

if (!detail || !editingBlock || !patchDraft.text.trim()) {
    showError(null, '请先选择内容块并填写 patch 预览。');
    return;
}

if (!detail || !editingBlock) {
    showError(null, '请先选择需要局部修改的内容块。');
    return;
}

if (start < 0 || end <= start || end > currentText.length || !selectedText || !selectionPatchDraft.replacement.trim()) {
    showError(null, '选区边界或替换文本无效，请按当前正文重新选择。');
    return;
}

before:
onClick={() => { if (selectedId) {
    setSelectedId('');
    setDetail(null);
    setPreview(null);
    setBookDraft(emptyBookDraft);
} setEditorOpen(true); }}
